fields.InputDefinition:
{
  "goal": "Switch to the Admin application via the application switcher dropdown next to the logo, open 'Identity & Access', and select the 'App Roles' sub-section. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) app-roles-list — the Application Roles view renders applications as expandable accordion panels with role-assignment rows (or an open-access message); (2) toggle-discard — expand any application group and toggle one of its 'Can Access' or 'Can Admin' checkboxes, confirm an 'Unsaved changes' badge appears in the header along with 'Discard' and 'Save Changes' buttons, then click 'Discard' and confirm the unsaved-state chrome clears (badge and buttons disappear); (3) add-role-assignment — at the bottom of an expanded panel, pick an unassigned role from the 'Select a role to add...' dropdown and click 'Add Role', then confirm a new role row is added (marked with a 'new' badge) and the 'Unsaved changes' state appears. Do NOT click Save. Keep going until every section has been visited. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200/app/admin",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "app-roles-list",
      "instruction": "open the App Roles matrix",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/admin"
        }
      ],
      "visualCriteria": [
        "The App Roles view renders applications as expandable accordion panels with role-assignment rows (or a clear open-access message)"
      ]
    },
    {
      "name": "toggle-discard",
      "instruction": "toggle a role checkbox then discard",
      "visualCriteria": [
        "Toggling a Can Access / Can Admin checkbox surfaces an 'Unsaved changes' badge plus Discard and Save Changes buttons, and clicking Discard clears the unsaved-changes indicators"
      ]
    },
    {
      "name": "add-role-assignment",
      "instruction": "add an unassigned role to an app",
      "visualCriteria": [
        "Selecting an unassigned role from the dropdown and clicking 'Add Role' inserts a new role row (with a 'new' indicator) into that application's assignments and an unsaved-changes indicator appears"
      ]
    }
  ]
}
